--- a/src/core/project.ts
+++ b/src/core/project.ts
@@ -6,12 +6,68 @@ export interface Record {
   warns: readonly string[];
 }

+const extractKeywords = (text: string): Set<string> => {
+  const stopwords = new Set([
+    'the', 'a', 'an', 'and', 'or', 'but', 'in', 'on', 'at', 'to', 'for', 'of', 'with', 'by', 'from', 'up', 'about', 'into', 'through', 'no', 'not', 'that', 'this', 'will', 'would', 'could', 'has', 'have', 'one', 'more', 'same', 'as', 'we', 'they', 'someone', 'another', 'do', 'does', 'is', 'add', 'take', 'new'
+  ]);
+
+  const words = text
+    .toLowerCase()
+    .replace(/[^\w\s-]/g, ' ')
+    .split(/\s+/)
+    .filter(word => word.length > 2 && !stopwords.has(word));
+
+  return new Set(words);
+};
+
+const computeSimilarity = (a: Set<string>, b: Set<string>): number => {
+  if (a.size === 0 && b.size === 0) return 1;
+  if (a.size === 0 || b.size === 0) return 0;
+
+  const intersection = new Set([...a].filter(x => b.has(x)));
+  const union = new Set([...a, ...b]);
+
+  return intersection.size / union.size;
+};
+
+const deduplicateSimilar = (entries: readonly string[]): string[] => {
+  if (entries.length === 0) return [];
+
+  const result: string[] = [];
+  const used = new Set<number>();
+  const threshold = 0.25; // Keep entries that share 25%+ of keywords
+
+  for (let i = 0; i < entries.length; i++) {
+    if (used.has(i)) continue;
+
+    result.push(entries[i]);
+    const keysI = extractKeywords(entries[i]);
+
+    for (let j = i + 1; j < entries.length; j++) {
+      if (used.has(j)) continue;
+
+      const keysJ = extractKeywords(entries[j]);
+      if (computeSimilarity(keysI, keysJ) >= threshold) {
+        used.add(j);
+      }
+    }
+  }
+
+  return result;
+};
+
 export const project = (records: readonly Record[]): string => {
   const lines: string[] = [];
+
   for (const record of records) {
-    for (const entry of record.ruledOut) lines.push(`- ruled out: ${entry}`);
-    for (const limit of record.limits) lines.push(`- limit: ${limit}`);
-    for (const warn of record.warns) lines.push(`- warn: ${warn}`);
+    const uniqueRuledOut = deduplicateSimilar(record.ruledOut);
+    const uniqueLimits = deduplicateSimilar(record.limits);
+    const uniqueWarns = deduplicateSimilar(record.warns);
+
+    for (const entry of uniqueRuledOut) lines.push(`- ruled out: ${entry}`);
+    for (const limit of uniqueLimits) lines.push(`- limit: ${limit}`);
+    for (const warn of uniqueWarns) lines.push(`- warn: ${warn}`);
   }
+
   return lines.join("\n");
 };
